import type { ReactNode } from "react";

function IconPlaceholder({
  children,
  label,
}: {
  children: ReactNode;
  label: string;
}) {
  return (
    <span
      aria-label={`${label} icon placeholder`}
      className="tech-icon text-foreground flex size-5 items-center justify-center font-mono text-[9px] leading-none"
      role="img"
    >
      {children}
    </span>
  );
}

